'use strict';
// Content presentation and user actions; domain transitions live in workflow-model.js.
function txt(zh,en){if(typeof uiMessages!=='undefined'){uiMessages[zh]=en;uiEnglishToChinese[en]=zh;if(typeof phrasePattern!=='undefined')phrasePattern=null;}return zh;}
const flowHandlers={};
const flowButton=(zh,en,flow,id='',style='')=>`<button class="btn ${style}" data-flow="${flow}" data-flow-id="${esc(id)}">${txt(zh,en)}</button>`;
const statusWords={queued:['排队中','Queued'],verifying:['核验中','Verifying'],published:['已公开','Published'],unpublished:['已下线','Unpublished'],uncertain:['结果未知','Outcome unknown'],failed:['执行失败','Failed'],blocked:['权限或条件已变化','Blocked'],cancelled:['已取消','Cancelled'],approval_needed:['等待组织批准','Awaiting organization approval'],ready:['待执行','Ready'],manual_action_needed:['待人工处理','Manual action needed'],submitted:['已提交','Submitted'],reviewing:['审核中','Under review'],rejected:['已拒绝','Rejected'],removed:['已移除','Removed'],scheduled:['稍后人工执行','Waiting for human action'],draft:['草稿','Draft'],changed:['有未发布更改','Unpublished changes'],connected:['已连接并核验','Connected & verified'],unconfigured:['未连接','Not connected'],pending:['等待 NyxID 返回','Awaiting NyxID return'],unbound:['已连接，待绑定','Connected; binding needed'],expired:['连接已失效','Connection expired'],mismatch:['账号归属不匹配','Account ownership mismatch'],unsupported:['当前不支持','Not supported']};
function statusBadge(code){const label=statusWords[code]||[code,code];return badge(txt(...label),['published','connected'].includes(code)?'green':['failed','rejected','mismatch'].includes(code)?'red':['queued','verifying','ready','changed'].includes(code)?'purple':['uncertain','approval_needed','blocked','unbound','expired'].includes(code)?'amber':'neutral',true);}
function workflowErrorText(message){return uiEnglishToChinese[message]||message;}
function flowError(message){toast(txt('操作未完成：','Action not completed: ')+workflowErrorText(message));}
articleStatus=function(a){return `<div class="language-statuses">${Object.keys(a.langs).filter(k=>canReadLanguage(a,k)).map(k=>`<span><b>${k.toUpperCase()}</b> ${statusBadge(languageState(a,k))}<small>v${readableLanguage(a,k).version}${a.langs[k].submittedSnapshot?' · '+txt('提交','Submitted')+' v'+a.langs[k].submittedSnapshot.version:''}</small></span>`).join('')}</div>`;};
const mdRenderer=markdownit({html:false,linkify:false,typographer:false});
mdRenderer.renderer.rules.image=(tokens,index,options,env)=>{const token=tokens[index],src=token.attrGet('src')||'',media=prototypeMedia.get(src);const a=env.article||current(),lang=env.lang||state.lang;const allowed=media&&media.owner===a.owner&&media.articleId===a.id&&media.lang===lang&&(env.public?media.publicVersions?.has(env.version):canReadLanguage(a,lang));return allowed?`<figure class="markdown-media"><img src="${esc(media.url)}" alt="${esc(token.content)}"><figcaption>${esc(token.content)}</figcaption></figure>`:`<span class="media-unavailable">${esc(token.content||'Image')} · ${txt('图片尚未导入或当前无权查看','Image not imported or unavailable')}</span>`;};
renderMarkdown=function(body,context={}){return mdRenderer.render(String(body).replace(/^\uFEFF/,''),context);};
publicPreview=function(frozen=null){const l=frozen||snapshot(language()),a=current();return `<div class="public-preview"><div class="publication-name">${mark}<span data-i18n-preserve>${esc(site.settings[a.owner].name)}</span><span class="mono">JOURNAL</span></div><div class="eyebrow">${state.lang.toUpperCase()} · v${l.version}</div><h2 data-i18n-preserve>${esc(l.savedTitle)}</h2><div class="preview-byline"><span class="avatar">${a.initials}</span><strong>${esc(a.author)}</strong><span>· v${l.version}</span></div><div class="article-excerpt exact-preview" data-i18n-preserve>${renderMarkdown(l.savedBody,{article:a,lang:state.lang})}</div></div>`;};
function normalizedMarkdown(text){return String(text).replace(/\r\n?/g,'\n');}
save=function(){if(!canEdit())return flowError('Only the author can edit this draft');const l=language();if(!l.title.trim()||!l.body.trim())return flowError('Title and Markdown are required');if(state.conflict)return actions['conflict-detail']();if(!dirty())return;
 const body=normalizedMarkdown(l.body)===normalizedMarkdown(l.savedBody)?l.savedBody:l.body;revisionList(l);l.savedBody=body;l.body=body;l.savedTitle=l.title;l.version++;l.revisions.push(Object.freeze({...snapshot(l),createdAt:nowStamp()}));if(state.lang==='en'&&current().langs.zh)current().langs.zh.stale=true;current().updated='刚刚';render();toast(txt('已保存新修订；线上版本未改变。','New revision saved; the live version is unchanged.'));};
actions.save=()=>save();
function jobHistory(j){return `<ol class="timeline">${j.events.map(e=>`<li>${statusBadge(e.state)}<small>${e.time}${e.note?' · '+esc(e.note):''}</small></li>`).join('')}</ol>`;}
function originalTaskCard(j){if(!j)return '';return `<section class="panel workflow-task"><div class="section-heading"><h3>${txt('原文任务','Original task')} <span class="mono">${j.id}</span></h3>${statusBadge(j.status)}</div><p data-i18n-preserve>${esc(j.snapshot.savedTitle)}</p><p class="secondary">${workspaceLabel(j.owner)} · ${j.lang.toUpperCase()} · v${j.snapshot.version} · ${j.host}</p><div class="workflow-actions">${['queued'].includes(j.status)?flowButton('取消待发','Cancel pending','cancel-original',j.id,'sm'):''}${j.status==='uncertain'?flowButton('只读核验结果','Verify existing result','verify-original',j.id,'sm primary'):''}${['failed','blocked','cancelled'].includes(j.status)?flowButton('重新确认版本','Confirm a new task','open-original-editor',j.id,'sm'):''}${flowButton('查看文章','View article','original-article',j.id,'sm quiet')}${flowButton('查看任务历史','Task history','original-history',j.id,'sm quiet')}</div>${j.mediaStatus&&j.mediaStatus!=='ready'?notice(txt(j.mediaStatus==='verifying'?'正在核验当前公开版本的图片。':'原文已公开，部分图片尚未完成公开转存。',j.mediaStatus==='verifying'?'Verifying images for the current public version.':'The original is public; some images still need public materialization.'))+(['incomplete','failed'].includes(j.mediaStatus)?flowButton('补齐公开图片','Complete public images','complete-images',j.id,'sm primary'):''):''}</section>`;}
publishPage=function(){const a=current(),l=language(),j=latestOriginal();const pending=j&&['queued','verifying','uncertain'].includes(j.status);const frozen=pending?j.snapshot:snapshot(l);const problem=confirmationProblem();return routeButton('返回编辑器','editor','quiet','back')+titleBlock('READY TO SHARE',canPublish()?'确认发布':'提交发布',txt('核对实际正文、版本、归属和目标语言站点。','Review the exact content, version, ownership and destination site.'))+`<div class="review-grid"><section class="panel review-preview"><div class="panel-header"><strong>${txt('确定内容预览','Exact content preview')}</strong><small>v${frozen.version} · ${state.lang.toUpperCase()}</small></div>${publicPreview(frozen)}</section><aside class="review-side"><section class="panel review-summary"><h3>${txt('发布摘要','Publication summary')}</h3>${[['内容所有者','Content owner',workspaceLabel()],['署名作者','Author',a.author],['语言与版本','Language & version',`${state.lang.toUpperCase()} · v${frozen.version}`],['目标站点','Destination',publicationTarget().displayAddress]].map(([zh,en,v])=>`<div class="review-line"><span>${txt(zh,en)}</span><strong data-i18n-preserve>${esc(v)}</strong></div>`).join('')}<p>${txt('只处理当前语言；其他语言及已知副本保持独立。','Only this language is affected. Other languages and known copies remain independent.')}</p>${problem?notice(problem):''}${!pending?`${canPublish()?`<div class="rights"><input type="checkbox" class="check" id="rights-confirm" ${state.rights?'checked':''}><label for="rights-confirm">${txt('我已核对正文，并确认文字和图片的发布权利。','I reviewed the content and confirm my rights to publish its text and images.')}</label></div>`:''}${btn(canPublish()?(l.live?'确认更新原文':'确认发布原文'):'确认提交当前版本','confirm-publish','primary full','',problem||(canPublish()&&!state.rights)?'disabled':'')}`:notice(txt('任务已创建。可以离开本页，任务会继续；取消需使用明确操作。','The task continues when you leave this page. Use an explicit cancellation to stop pending work.'))}</section>${originalTaskCard(j)}${state.release==='submitted'?notice(txt('确定版本已提交。后续草稿编辑不会改变这次提交。','The exact version was submitted. Later edits will not change it.')):''}${notice(txt('原文发布不增加组织 Admin 审批。外部组织自动写入另行请求精确批准。','Original publication requires no extra Admin review. Automatic external organization writes require separate exact approval.'))}</aside></div>`;};
pageRenderers.publish=publishPage;
confirmationProblem=function(){if(!site.signedIn||!accessibleWorkspace(state.workspace)||current().owner!==state.workspace)return txt('当前工作区或文章不可访问。','The workspace or article is unavailable.');if(!canPublish()&&!canSubmit())return txt('只能提交自己创建的组织草稿。','Only your own organization drafts can be submitted.');if(state.conflict)return txt('请先处理版本冲突。','Resolve the editing conflict first.');if(dirty())return txt('请先保存草稿。','Save the draft first.');if(!language().savedTitle.trim()||!language().savedBody.trim())return txt('标题和正文不能为空。','Title and body are required.');if(canPublish()&&!isSiteReady(state.workspace,state.lang))return txt('当前语言站点尚未开通；仍可保存草稿。','This language site is not provisioned; drafts can still be saved.');return null;};
actions['confirm-publish']=()=>{const problem=confirmationProblem();if(problem)return toast(problem);const l=language();if(!canPublish()){l.submitted=l.version;l.submittedSnapshot=snapshot(l);state.release='submitted';render();return;}const j=createOriginalJob(l.live?'update':'publish');if(!j)return flowError('Confirm rights and resolve existing pending tasks first');state.rights=false;render();};
actions.history=()=>{const rows=readableRevisions(current(),state.lang);modal(txt('版本历史','Version history'),`<p>${txt('仅展示当前身份可访问的修订。查看旧版不会修改草稿或线上版本。','Only accessible revisions are shown. Viewing a revision never changes the draft or live version.')}</p>${rows.slice().reverse().map(r=>`<div class="history-item"><div><strong>v${r.version} <span data-i18n-preserve>${esc(r.savedTitle)}</span></strong><small>${r.createdAt||'14:00'}</small></div>${flowButton('查看与下载','View & download','view-revision',String(r.version),'sm')}</div>`).join('')}`,btn('关闭','close-modal'));};
flowHandlers['view-revision']=version=>{const r=selectedRevision(current(),state.lang,version);if(!r)return flowError('Revision is not accessible');modal(txt('查看修订','View revision')+' · v'+r.version,publicPreview(r),flowButton('下载此修订','Download this revision','download-revision',version)+btn('关闭','close-modal'),true);};
flowHandlers['download-revision']=version=>{const r=selectedRevision(current(),state.lang,version);if(r)download(`revision-${version}.md`,r.savedBody);};
flowHandlers['original-history']=id=>{const j=originalJobs.find(x=>x.id===id);if(j&&j.owner===state.workspace&&canPublishOwner(j.owner))modal(txt('原文任务历史','Original task history'),jobHistory(j),btn('关闭','close-modal'));};
flowHandlers['cancel-original']=id=>{cancelJob(originalJobs.find(x=>x.id===id));render();};
flowHandlers['open-original-editor']=id=>{const j=originalJobs.find(x=>x.id===id);if(!j||j.owner!==state.workspace)return;openArticle(j.articleId,'publish');state.lang=j.lang;render();};
flowHandlers['verify-original']=id=>{const j=originalJobs.find(x=>x.id===id);if(!j||!taskAuthorized(j)||j.owner!==state.workspace)return;modal(txt('只读核验','Read-only verification'),`<p>${txt('核验不会重新发布、同步译文或公开新图片。','Verification does not republish, synchronize translations or publish new images.')}</p>${jobHistory(j)}`,flowButton('仍未知','Still unknown','original-still',id)+flowButton(j.action==='unpublish'?'原文仍公开':'未找到本次公开版本',j.action==='unpublish'?'Original still public':'Confirmed version not found','original-'+(j.action==='unpublish'?'found':'missing'),id)+flowButton(j.action==='unpublish'?'演示：已核验下线':'演示：已核验公开',j.action==='unpublish'?'Demo: verified unpublished':'Demo: verified public','original-'+(j.action==='unpublish'?'missing':'found'),id,'primary'));};
for(const [command,result] of [['original-still','unknown'],['original-missing','missing'],['original-found','published']])flowHandlers[command]=id=>{reconcileOriginal(originalJobs.find(j=>j.id===id),result);closeModal();render();};
actions.unpublish=()=>{if(!canPublish())return;modal(txt('下线当前语言','Unpublish this language'),`<p>${txt('外部副本不会自动移除。原文下线后，仍可核验和处理已知副本。','External copies remain. Known copies can still be verified and managed after unpublishing.')}</p>`,btn('取消','close-modal')+flowButton('确认下线 · 演示','Confirm unpublish · Demo','queue-unpublish','','danger'));};
flowHandlers['queue-unpublish']=()=>{state.rights=true;const j=createOriginalJob('unpublish');state.rights=false;closeModal();if(!j)flowError('Resolve the pending original task first');render();};
let pendingMedia=null;
actions.image=()=>{if(!canEdit())return;pendingMedia={articleId:state.articleId,lang:state.lang,owner:state.workspace,file:null,url:null};modal(txt('插入私有图片','Insert private image'),`<p>${txt('图片属于当前文章和语言；此原型仅在本机预览，不上传。','The image belongs to this article and language. This prototype previews it locally without uploading.')}</p><div class="modal-field"><label for="private-image">${txt('选择 PNG、JPEG 或 WebP（最大 5 MB）','Choose PNG, JPEG or WebP (up to 5 MB)')}</label><input id="private-image" type="file" accept="image/png,image/jpeg,image/webp"></div><div id="media-preview"></div><div class="modal-field"><label for="media-alt">${txt('图片描述','Image description')}</label><input id="media-alt"></div><p class="form-error" id="media-error" role="alert"></p>`,btn('取消','close-modal')+flowButton('插入文章','Insert into article','insert-media','','primary'));};
flowHandlers['insert-media']=()=>{const m=pendingMedia,alt=document.getElementById('media-alt')?.value.trim();if(!m?.file||!alt){document.getElementById('media-error').textContent=txt('请选择图片并填写描述。','Select an image and add a description.');return;}if(!canEdit()||m.articleId!==state.articleId||m.lang!==state.lang||m.owner!==state.workspace)return flowError('The editing context changed');const id='asset:'+nextWorkflowId('image');prototypeMedia.set(id,m);language().body+=`\n\n![${alt.replace(/[\[\]\n]/g,' ')}](${id})\n`;pendingMedia=null;closeModal();render();};
document.addEventListener('change',event=>{if(event.target.id!=='private-image')return;const f=event.target.files?.[0],m=pendingMedia;event.target.value='';if(!m)return;if(m.url)URL.revokeObjectURL(m.url);m.file=null;m.url=null;const error=document.getElementById('media-error');if(!f||f.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type)){error.textContent=txt('文件格式或大小不符合要求，请重新选择。','Unsupported file type or size. Choose another file.');return;}m.file=f;m.url=URL.createObjectURL(f);error.textContent='';document.getElementById('media-preview').innerHTML=`<img class="upload-preview" src="${m.url}" alt="${esc(f.name)}"><p>${esc(f.name)}</p>`;});
const closeWorkflowModal=closeModal;closeModal=function(){if(pendingMedia?.url)URL.revokeObjectURL(pendingMedia.url);pendingMedia=null;closeWorkflowModal();};
document.addEventListener('click',event=>{const el=event.target.closest('[data-flow]');if(!el||el.disabled)return;event.preventDefault();const handler=flowHandlers[el.dataset.flow];if(handler)handler(el.dataset.flowId,el);});

flowHandlers['complete-images']=id=>{const j=originalJobs.find(x=>x.id===id);if(!j||!taskAuthorized(j)||j.owner!==state.workspace)return;modal(txt('确认补齐公开图片','Confirm public image completion'),`<p>${workspaceLabel(j.owner)} · ${j.lang.toUpperCase()} · v${j.snapshot.version}</p><p data-i18n-preserve>${esc(j.snapshot.savedTitle)}</p>${notice(txt('仅补齐该公开版本引用的图片，不更新正文或其他语言。确认时重验发布权限、公开版本与图片权利。','Complete only images referenced by this public version. Text and other languages are unchanged. Publishing permission, live version and image rights are rechecked.'))}<label class="rights"><input type="checkbox" id="image-rights">${txt('确认该版本图片具有公开发布权利。','I confirm the right to publicly publish the images in this version.')}</label><p id="image-completion-error" class="form-error"></p>`,btn('取消','close-modal')+flowButton('确认补图 · 演示','Confirm image completion · Demo','confirm-images',id,'primary'));};
flowHandlers['confirm-images']=id=>{if(!completeMissingImages(originalJobs.find(j=>j.id===id),document.getElementById('image-rights').checked)){document.getElementById('image-completion-error').textContent=translateUi(txt('请确认图片权利，并核对当前发布权限和版本。','Confirm image rights and check the current publishing permission and version.'));return;}closeModal();render();};

flowHandlers['original-article']=id=>{const j=originalJobs.find(x=>x.id===id);if(!j||j.owner!==state.workspace||!canReadLanguage(articles.find(a=>a.id===j.articleId),j.lang))return;closeModal();openArticle(j.articleId,'distribution');state.lang=j.lang;render();};
displayLanguage=function(a){return readableLanguage(a,preferredArticleLanguage(a))||{savedTitle:'暂无可查看版本',savedBody:''};};
